import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { Link } from 'react-router-dom';
import * as XLSX from 'xlsx';
import { AdminLayout } from '../AdminLayout';
import { useSupabaseAuth } from '../../auth/SupabaseAuthProvider';
import {
  buildInventoryMenuRecipeRows, filterInventoryItemsByArea, filterInventoryStockItems, formatConfiguredInventoryQuantity, formatInventoryMoneyInput, formatInventoryQuantity, getInventoryItemSearchSelection, getInventoryMessageDuration, inventoryAreaName, inventoryItemMatchesSearch, inventoryMoneyInput, inventoryMonthValue, inventoryMovementCsv, inventoryUnitLabels, movementLabels, parseInventorySubmissionLineNotes, receiptCostPreview, submissionKindLabels, summarizeInventoryRecipeCost,
  type InventoryArea, type InventoryAreaDefinition, type InventoryCursor, type InventoryData, type InventoryItem, type InventoryMenuRecipeStatus, type InventoryReceipt, type InventoryStockAreaFilter, type InventoryStockOrder, type InventoryStockStatusFilter, type InventorySubmission, type InventorySubmissionKind, type InventoryUnit, type InventoryUsageType, type PosInventoryArea,
} from './inventory.domain';
import { createInventoryTemplateWorkbook, inventoryImportFingerprint, parseInventoryWorkbook, type ParsedInventoryImport } from './inventory-import';
import { commitInventoryImport, deleteInventoryConfiguration, downloadInventoryCsv, loadInventory, loadInventoryMovementExport, loadInventoryMovementsPage, loadInventoryPendingReplenishments, loadInventoryReceiptsPage, loadInventorySubmissionsPage, previewInventoryImport, saveInventoryCommand, saveInventoryPurchase, subscribeToInventoryRealtime, type InventoryImportServerPreview, type InventoryRealtimeEventKind } from './inventory.repository';
import { InventoryStatusBadge, InventorySubmissionStage, inventoryStatusLabels } from './InventoryStatusBadge';
import { InventoryPurchaseLinesEditor, buildInventoryPurchaseLines, createInventoryPurchaseLine, inventoryPurchaseLinesValid, inventoryPurchaseTotal, type InventoryPurchaseDraftLine } from './InventoryPurchaseLinesEditor';
import { loadCash } from '../cash/cash.repository';
import { bogotaToday, methods, origins, type CashData } from '../cash/cash.domain';

type Tab = 'stock' | 'receipts' | 'requests' | 'history' | 'recipes' | 'configuration';
type Modal = 'receive' | 'submit' | 'item' | 'presentation' | 'recipe' | 'adjust' | 'import' | 'area' | null;

const money = (value: number) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 2 }).format(value);
const dateTime = (value: string) => new Date(value).toLocaleString('es-CO', { timeZone: 'America/Bogota' });
const tabLabels: Record<Tab, string> = { stock: 'Existencias', receipts: 'Entradas', requests: 'Solicitudes y conteos', history: 'Historial', recipes: 'Consumo del menú', configuration: 'Configuración' };

const emptyData: InventoryData = { can_manage: false, can_configure: false, pending_review_count: 0, areas: [], items: [], presentations: [], recipes: [], menu_items: [], submissions: [], receipts: [], movements: [] };

const purchasePaymentLabel = (purchase: NonNullable<InventoryReceipt['purchase']>) => purchase.payment_status === 'legacy_unlinked'
  ? 'Histórico · pago no registrado'
  : purchase.payment_status === 'pending'
    ? 'Pago pendiente'
    : purchase.payment_origin ? origins[purchase.payment_origin] : 'Pagada';

const purchaseLinkLabel = (purchase: NonNullable<InventoryReceipt['purchase']>) => purchase.payment_status === 'legacy_unlinked'
  ? 'Sin vínculo financiero histórico'
  : purchase.payment_status === 'paid' ? 'Gasto vinculado ✓' : 'Sin gasto pagado';

export function AdminInventoryView() {
  const { hasRole, isCatalogAdmin, staffRoles, user } = useSupabaseAuth();
  const [data, setData] = useState<InventoryData>(emptyData);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [tab, setTab] = useState<Tab>('stock');
  const [stockUsageType, setStockUsageType] = useState<InventoryUsageType | 'all'>('all');
  const inventoryCache = useRef<Partial<Record<InventoryUsageType | 'all', InventoryData>>>({});
  const [modal, setModal] = useState<Modal>(null);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [editingItem, setEditingItem] = useState<InventoryItem | null>(null);
  const [editingPresentation, setEditingPresentation] = useState<InventoryData['presentations'][number] | null>(null);
  const [editingArea, setEditingArea] = useState<InventoryAreaDefinition | null>(null);
  const [selectedRecipeMenuKey, setSelectedRecipeMenuKey] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [sectionRefreshVersions, setSectionRefreshVersions] = useState({ receipts: 0, requests: 0, history: 0 });
  const purchasePendingKey=`zafiro-inventory-purchase-pending:${user?.id??''}`;
  const [purchasePending,setPurchasePending]=useState<{id:string;payload:Record<string,unknown>}|null>(()=>{try{return JSON.parse(localStorage.getItem(purchasePendingKey)??'null');}catch{return null;}});
  const refreshRequestIdRef = useRef(0);
  const operationalArea: PosInventoryArea | null = hasRole('kitchen') ? 'kitchen' : hasRole('bar') ? 'bar' : null;
  const mayOpen = isCatalogAdmin || staffRoles.some((role) => ['superadmin','cashier','bar','kitchen'].includes(role));

  const selectStockUsageType = (next: InventoryUsageType | 'all') => {
    const cached = inventoryCache.current[next];
    if (cached) { setData(cached); setLoading(false); }
    else setLoading(true);
    setStockUsageType(next);
  };

  const refresh = useCallback(async (force = false, background = false) => {
    const key: InventoryUsageType | 'all' = tab === 'stock' ? stockUsageType : 'all';
    const cached = inventoryCache.current[key];
    if (!force && cached) { setData(cached); setLoading(false); return; }
    const requestId = ++refreshRequestIdRef.current;
    if (!background) setLoading(true);
    setError(null);
    try { const next = await loadInventory(key === 'all' ? null : key); if(requestId===refreshRequestIdRef.current){inventoryCache.current[key] = next; setData(next);} }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudo cargar inventario.'); }
    finally { if(!background)setLoading(false); }
  }, [stockUsageType, tab]);
  const refreshRef = useRef(refresh);
  refreshRef.current = refresh;
  const refreshSections = useCallback((kinds?: InventoryRealtimeEventKind[]) => {
    const refreshAll=!kinds;
    setSectionRefreshVersions((current)=>({
      receipts:current.receipts+(refreshAll||kinds.includes('receipt')?1:0),
      requests:current.requests+(refreshAll||kinds.includes('submission')?1:0),
      history:current.history+(refreshAll||kinds.includes('movement')?1:0),
    }));
  },[]);
  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => {
    if(!mayOpen)return undefined;
    return subscribeToInventoryRealtime((kinds)=>{
      inventoryCache.current={};
      refreshSections(kinds);
      void refreshRef.current(true,true);
    });
  },[mayOpen,refreshSections]);
  useEffect(() => {
    if (!notice && !error) return undefined;
    const timer = window.setTimeout(() => {
      setNotice(null);
      setError(null);
    }, getInventoryMessageDuration(Boolean(error)));
    return () => window.clearTimeout(timer);
  }, [error, notice]);

  const run = async (payload: Record<string, unknown>, message: string) => {
    setBusy(true); setError(null); setNotice(null);
    try {
      let requestId:string=crypto.randomUUID();
      if(payload.action==='purchase'){
        const saved=JSON.parse(localStorage.getItem(purchasePendingKey)??'null') as {id:string;payload:Record<string,unknown>}|null;
        if(saved&&JSON.stringify(saved.payload)!==JSON.stringify(payload))throw new Error('Hay una compra pendiente de confirmar. Reintenta la misma operación antes de registrar otra.');
        const pending=saved??{id:requestId,payload}; requestId=pending.id; localStorage.setItem(purchasePendingKey,JSON.stringify(pending));setPurchasePending(pending);
        await saveInventoryPurchase(requestId,payload); localStorage.removeItem(purchasePendingKey);setPurchasePending(null);
      } else await saveInventoryCommand(requestId, payload);
      inventoryCache.current = {}; setNotice(message); setModal(null); setSelectedItemId(null); refreshSections(); await refresh(true);
    } catch (reason) { if((reason as {confirmedRejection?:boolean}).confirmedRejection){localStorage.removeItem(purchasePendingKey);setPurchasePending(null);}setError(reason instanceof Error ? reason.message : 'No se pudo guardar.'); }
    finally { setBusy(false); }
  };
  const remove = async (payload: Record<string, unknown>, label: string) => {
    if (!window.confirm(`¿Eliminar ${label}? Solo se permitirá si nunca se ha utilizado.`)) return;
    setBusy(true); setError(null); setNotice(null);
    try { await deleteInventoryConfiguration(crypto.randomUUID(),payload); inventoryCache.current={}; setNotice(`${label} se eliminó.`); setModal(null); refreshSections(); await refresh(true); }
    catch(reason){ setError(reason instanceof Error?reason.message:'No se pudo eliminar.'); }
    finally { setBusy(false); }
  };

  if (!mayOpen) return <AdminLayout><StateCard title="Acceso denegado">Tu rol no tiene acceso al inventario.</StateCard></AdminLayout>;

  const tabs = (['stock','receipts','requests','history', ...(data.can_configure ? ['recipes','configuration'] : [])] as Tab[]);
  return (
    <AdminLayout>
      <section className="flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
        <div><p className="text-[0.7rem] uppercase tracking-[0.25em] text-cyanGlow/80">Operación ZAFIRO</p><h1 className="mt-3 font-display text-[2.6rem] leading-none text-ivory sm:text-[3.5rem]">Inventario</h1>
          <p className="mt-4 max-w-3xl text-sm leading-7 text-mist">Existencias compartidas del local. Las áreas controlan quién consulta y reporta; los saldos cambian solo mediante movimientos auditados.</p></div>
        <div className="flex flex-wrap gap-2"><Link to="/admin/pos" className={ghostButton}>Volver al POS</Link><button className={ghostButton} onClick={() => void refresh(true)}>Actualizar</button></div>
      </section>

      {error ? <div role="alert" className={modal?'fixed left-1/2 top-4 z-[70] w-[min(42rem,calc(100%-2rem))] -translate-x-1/2 rounded-[1rem] border border-rose-300/35 bg-[#35151d] p-4 text-sm text-rose-100 shadow-2xl':'mt-6 rounded-[1rem] border border-rose-300/30 bg-rose-300/10 p-4 text-sm text-rose-100'}>{error} <button onClick={() => modal?setError(null):void refresh()} className="ml-2 underline">{modal?'Cerrar aviso':'Reintentar'}</button></div> : null}
      {notice ? <div className="mt-6 rounded-[1rem] border border-emerald-300/25 bg-emerald-300/10 p-4 text-sm text-emerald-100">{notice}</div> : null}
      {purchasePending ? <div className="mt-6 flex flex-wrap items-center justify-between gap-3 rounded-[1rem] border border-amberGlow/25 bg-amberGlow/[0.08] p-4 text-sm text-amber-100"><span>Hay una compra pendiente de confirmar. El reintento conserva la misma solicitud para evitar duplicados.</span><button type="button" className={ghostButton} disabled={busy} onClick={()=>void run(purchasePending.payload,'Compra y entrada confirmadas.')}>Reintentar compra</button></div>:null}
      {loading && tab !== 'stock' ? <StateCard title="Cargando inventario">Consultando existencias y configuración…</StateCard> : (
        <>
          <section className="mt-7 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <Metric label="Artículos activos" value={String(data.items.filter((item) => item.active).length)} />
            <Metric label="Sin conteo inicial" value={String(data.items.filter((item) => item.balance == null).length)} tone="warn" />
            <Metric label="Bajo mínimo" value={String(data.items.filter((item) => item.balance != null && item.minimum_quantity != null && item.balance < item.minimum_quantity).length)} tone="warn" />
            <Metric label="Pendientes de revisión" value={String(Number(data.pending_review_count ?? 0))} />
          </section>
          <nav className="mt-7 flex gap-2 overflow-x-auto pb-2">{tabs.map((value) => <button key={value} onClick={() => setTab(value)} className={`${tabButton} ${tab === value ? 'border-cyanGlow/45 bg-cyanGlow/14 text-cyanGlow' : 'border-white/10 bg-white/[0.03] text-mist'}`}>{tabLabels[value]}</button>)}</nav>
          {tab === 'stock' ? <StockTab data={data} loading={loading} usageType={stockUsageType} onUsageTypeChange={selectStockUsageType} onReceive={(itemId) => { setSelectedItemId(itemId); setModal('receive'); }} onAdjust={(itemId) => { setSelectedItemId(itemId); setModal('adjust'); }} /> : null}
          {tab === 'receipts' ? <ReceiptsTab refreshVersion={sectionRefreshVersions.receipts} data={data} onReceive={() => { setSelectedItemId(null); setModal('receive'); }} /> : null}
          {tab === 'requests' ? <RequestsTab refreshVersion={sectionRefreshVersions.requests} data={data} area={operationalArea} busy={busy} onCreate={() => setModal('submit')} onRun={run} /> : null}
          {tab === 'history' ? <HistoryTab refreshVersion={sectionRefreshVersions.history} data={data} /> : null}
          {tab === 'recipes' && data.can_configure ? <MenuRecipesTab data={data} onConfigure={(menuKey) => { setSelectedRecipeMenuKey(menuKey); setModal('recipe'); }} /> : null}
          {tab === 'configuration' && data.can_configure ? <ConfigurationTab data={data} onAction={(next) => { setEditingItem(null); setEditingPresentation(null); setEditingArea(null); setModal(next); }} onEditItem={(item) => { setEditingItem(item); setModal('item'); }} onEditPresentation={(presentation) => { setEditingPresentation(presentation); setModal('presentation'); }} onEditArea={(area) => { setEditingArea(area); setModal('area'); }} /> : null}
        </>
      )}

      {modal === 'receive' ? <ReceiveDialog key={`receive-${selectedItemId ?? 'global'}`} data={data} initialItemId={selectedItemId} pendingRefreshVersion={sectionRefreshVersions.requests} busy={busy} onClose={() => { setModal(null); setSelectedItemId(null); }} onSave={run} /> : null}
      {modal === 'submit' ? <SubmissionDialog data={data} area={operationalArea} busy={busy} onClose={() => setModal(null)} onSave={run} /> : null}
      {modal === 'item' ? <ItemDialog data={data} initial={editingItem} busy={busy} onClose={() => setModal(null)} onSave={run} onDelete={(id)=>void remove({action:'delete_item',id},'el artículo')} /> : null}
      {modal === 'area' ? <AreaDialog initial={editingArea} busy={busy} onClose={() => setModal(null)} onSave={run} onDelete={(code)=>void remove({action:'delete_area',code},'el área')} /> : null}
      {modal === 'presentation' ? <PresentationDialog data={data} initial={editingPresentation} busy={busy} onClose={() => setModal(null)} onSave={run} onDelete={(id)=>void remove({action:'delete_presentation',id},'la presentación')} /> : null}
      {modal === 'recipe' ? <RecipeDialog key={selectedRecipeMenuKey ?? 'first'} data={data} initialMenuKey={selectedRecipeMenuKey} busy={busy} onClose={() => { setModal(null); setSelectedRecipeMenuKey(null); }} onSave={run} /> : null}
      {modal === 'adjust' && selectedItemId ? <AdjustmentDialog key={`adjust-${selectedItemId}`} data={data} itemId={selectedItemId} busy={busy} onClose={() => { setModal(null); setSelectedItemId(null); }} onSave={run} /> : null}
      {modal === 'import' ? <InventoryImportDialog onClose={() => setModal(null)} onImported={async (message) => { setNotice(message); setModal(null); await refresh(true); }} /> : null}
    </AdminLayout>
  );
}

function StockTab({ data, loading, usageType, onUsageTypeChange, onReceive, onAdjust }: { data: InventoryData; loading: boolean; usageType: InventoryUsageType | 'all'; onUsageTypeChange: (value: InventoryUsageType | 'all') => void; onReceive: (itemId: string | null) => void; onAdjust: (itemId: string) => void }) {
  const [search,setSearch]=useState(''); const [area,setArea]=useState<InventoryStockAreaFilter>('all'); const [status,setStatus]=useState<InventoryStockStatusFilter>('all'); const [order,setOrder]=useState<InventoryStockOrder>('operational_priority');
  const filtered=useMemo(()=>filterInventoryStockItems(data.items,search,area,status,order),[data.items,search,area,status,order]);
  return <section className="mt-5">
    {loading ? <StateCard title="Cargando existencias">Consultando únicamente los artículos de esta categoría…</StateCard> : <>
    <div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className={sectionTitle}>Existencias actuales</h2><p className={sectionCopy}>“Sin conteo inicial” es distinto de cero. El stock puede quedar negativo y se muestra como alerta.</p></div>
      {data.can_manage ? <button className={primaryButton} onClick={() => onReceive(null)}>Registrar entrada</button> : null}</div>
    <div className="mt-5 grid gap-3 rounded-[1.1rem] border border-white/10 bg-white/[0.025] p-4 md:grid-cols-2 xl:grid-cols-5"><Field label="Buscar artículo"><input aria-label="Buscar existencias" className={inputClass} value={search} onChange={(event)=>setSearch(event.target.value)} placeholder="Nombre o código" /></Field><Field label="Tipo"><select aria-label="Filtrar existencias por tipo" className={inputClass} value={usageType} onChange={(event)=>onUsageTypeChange(event.target.value as InventoryUsageType|'all')}><option value="all">Todos</option><option value="consumable">Consumibles</option><option value="operational">Operativos</option></select></Field><Field label="Área"><select aria-label="Filtrar existencias por área" className={inputClass} value={area} onChange={(event)=>setArea(event.target.value as InventoryStockAreaFilter)}><option value="all">Todos</option>{data.areas.filter((entry)=>entry.active).map((entry)=><option key={entry.code} value={entry.code}>{entry.name}</option>)}</select></Field><Field label="Estado"><select aria-label="Filtrar existencias por estado" className={inputClass} value={status} onChange={(event)=>setStatus(event.target.value as InventoryStockStatusFilter)}><option value="all">Todos</option><option value="uncounted">Sin conteo inicial</option><option value="low">Bajo mínimo</option><option value="depleted">Agotados</option><option value="in_stock">Con stock</option></select></Field><Field label="Orden"><select aria-label="Ordenar existencias" className={inputClass} value={order} onChange={(event)=>setOrder(event.target.value as InventoryStockOrder)}><option value="operational_priority">Prioridad operativa</option><option value="name_asc">Nombre A-Z</option><option value="name_desc">Nombre Z-A</option></select></Field><p className="text-xs text-mist md:col-span-2 xl:col-span-5">Mostrando {filtered.length} de {data.items.length}. Prioridad operativa: sin conteo, agotados, bajo mínimo, reposición pendiente y disponibles.</p></div>
    {!data.items.length ? <StateCard title="Sin artículos">No hay artículos que coincidan con el tipo seleccionado.</StateCard> : !filtered.length ? <StateCard title="Sin resultados">No hay artículos que coincidan con la búsqueda y los filtros seleccionados.</StateCard> : <div className="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filtered.map((item) => <StockCard key={item.id} areaDefinitions={data.areas} item={item} showCost={data.can_manage} canManage={data.can_manage} onAdjust={()=>onAdjust(item.id)} onReceive={()=>onReceive(item.id)} />)}</div>}</>}
  </section>;
}

function StockCard({ areaDefinitions, item, showCost, canManage, onAdjust, onReceive }: { areaDefinitions: InventoryAreaDefinition[]; item: InventoryItem; showCost: boolean; canManage: boolean; onAdjust: () => void; onReceive: () => void }) {
  const uncounted = item.balance == null;
  const negative = item.balance != null && item.balance < 0;
  const low = item.balance != null && item.minimum_quantity != null && item.balance < item.minimum_quantity;
  const pendingIncoming = Number(item.pending_incoming ?? 0);
  const suggested = item.balance == null || item.target_quantity == null ? null : Math.max(item.target_quantity - item.balance - pendingIncoming, 0);
  return <article className={`rounded-[1.2rem] border p-5 ${negative ? 'border-rose-300/35 bg-rose-300/[0.07]' : low || uncounted ? 'border-amberGlow/30 bg-amberGlow/[0.06]' : 'border-white/10 bg-white/[0.035]'}`}>
    <div className="flex items-start justify-between gap-3"><div><h3 className="font-display text-2xl text-ivory">{item.name}</h3><p className="mt-1 text-xs uppercase tracking-[0.16em] text-mist">{item.areas.map((area) => inventoryAreaName(areaDefinitions, area)).join(' · ') || 'Sin área'}</p></div><span className="rounded-full border border-white/10 px-2.5 py-1 text-[0.62rem] uppercase tracking-[0.15em] text-mist">{inventoryUnitLabels[item.base_unit]}</span></div>
    <p className={`mt-5 text-2xl font-semibold ${negative ? 'text-rose-200' : 'text-cyanGlow'}`}>{formatInventoryQuantity(item.balance, item.base_unit, item.precision_scale)}</p>
    <div className="mt-4 grid grid-cols-2 gap-3 text-sm text-mist"><p>Mínimo<br/><strong className="text-ivory">{formatConfiguredInventoryQuantity(item.minimum_quantity, item.base_unit, item.precision_scale)}</strong></p><p>Objetivo<br/><strong className="text-ivory">{formatConfiguredInventoryQuantity(item.target_quantity, item.base_unit, item.precision_scale)}</strong></p></div>
    {suggested != null ? <p className="mt-4 rounded-[0.8rem] bg-black/20 px-3 py-2 text-xs text-mist">Sugerencia: objetivo {formatInventoryQuantity(item.target_quantity, item.base_unit)} − existencia {formatInventoryQuantity(item.balance, item.base_unit)} − aprobado pendiente {formatInventoryQuantity(pendingIncoming, item.base_unit)} = <strong className="text-cyanGlow">{formatInventoryQuantity(suggested, item.base_unit)}</strong></p> : null}
    {showCost ? <div className="mt-3 grid grid-cols-2 gap-3 text-xs text-mist"><p>Último costo real<br/><strong className="text-ivory">{item.last_unit_cost == null ? 'Sin compra con costo' : money(item.last_unit_cost)}</strong></p><p>Valor contable rastreado<br/><strong className="text-ivory">{item.inventory_value == null ? 'Sin valoración conocida' : money(item.inventory_value)}</strong></p></div> : null}
    {canManage ? <div className="mt-5 flex flex-wrap gap-2"><button type="button" className={ghostButton} onClick={onAdjust}>Conteo / corregir</button><button type="button" className={primaryButton} onClick={onReceive}>Registrar entrada</button></div> : null}
  </article>;
}

function ReceiptsTab({ data, onReceive, refreshVersion }: { data: InventoryData; onReceive: () => void; refreshVersion: number }) {
  const [rows,setRows]=useState<InventoryReceipt[]>([]); const [hasMore,setHasMore]=useState(false); const [loading,setLoading]=useState(data.can_manage); const [pageError,setPageError]=useState<string|null>(null); const [cursors,setCursors]=useState<Array<InventoryCursor|null>>([null]); const [page,setPage]=useState(0);
  const itemName = (id: string) => data.items.find((item) => item.id === id)?.name ?? id;
  useEffect(()=>{if(!data.can_manage)return undefined;let active=true;setLoading(true);setPageError(null);void loadInventoryReceiptsPage(cursors[page]).then((result)=>{if(active){setRows(result.rows);setHasMore(result.has_more);}}).catch((reason)=>{if(active)setPageError(reason instanceof Error?reason.message:'No se pudieron cargar las entradas.');}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[data.can_manage,page,cursors,refreshVersion]);
  const next=()=>{const last=rows[rows.length-1];if(!last)return;setCursors((current)=>[...current.slice(0,page+1),{timestamp:last.received_at,id:last.id}]);setPage((current)=>current+1);};
  if(!data.can_manage)return <section className="mt-5"><h2 className={sectionTitle}>Entradas de mercancía</h2><StateCard title="Consulta restringida">Las entradas y sus costos están disponibles únicamente para administración y caja.</StateCard></section>;
  return <section className="mt-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className={sectionTitle}>Entradas de mercancía</h2><p className={sectionCopy}>20 entradas por página, ordenadas de la más reciente a la más antigua.</p></div><button className={primaryButton} onClick={onReceive}>Registrar entrada</button></div>
    {pageError?<PageError message={pageError}/>:null}{loading?<p className="mt-5 text-sm text-cyanGlow">Cargando entradas…</p>:null}
    {!loading&&!pageError?<div className="mt-5 space-y-3">{rows.length ? rows.map((receipt) => <article key={receipt.id} className={card}><div className="flex flex-wrap justify-between gap-3"><div><p className="font-semibold text-ivory">{receipt.supplier || 'Proveedor sin registrar'}</p><p className="mt-1 text-sm text-mist">{dateTime(receipt.received_at)} · {receipt.received_by}</p></div><p className="text-cyanGlow">{receipt.total_cost == null ? 'Costo sin registrar' : money(receipt.total_cost)}</p></div>{receipt.purchase?<p className="mt-3 rounded-[0.7rem] border border-white/10 bg-black/15 px-3 py-2 text-sm text-mist">Compra #{receipt.purchase.id.slice(0,8)} · {purchasePaymentLabel(receipt.purchase)} · {purchaseLinkLabel(receipt.purchase)}</p>:null}<p className="mt-3 text-sm text-mist">Documento: {receipt.document_reference || 'Sin registrar'} · {receipt.lines.length} línea(s) · Gasto vinculado: {receipt.expense_movement_id || 'No'}</p><div className="mt-4 space-y-2">{receipt.lines.map((line) => { const receiptItem=data.items.find((item)=>item.id===line.item_id); const unit=receiptItem?.base_unit??line.content_unit_snapshot??'unit'; const precision=receiptItem?.precision_scale??3; const applied=Number(line.applied_submission_quantity??0); const excess=Math.max(Number(line.base_quantity)-applied,0); return <div key={line.id} className="rounded-[0.8rem] border border-white/8 bg-black/15 p-3 text-sm text-mist"><p className="font-semibold text-ivory">{itemName(line.item_id)} · {line.presentation_name_snapshot || 'Unidad base directa'}</p><p className="mt-1">{line.package_quantity == null ? `${line.base_quantity} unidades base` : `${line.package_quantity} envase(s) · ${line.content_per_package_snapshot} ${line.content_unit_snapshot ? inventoryUnitLabels[line.content_unit_snapshot] : ''}`}</p>{line.submission_line_id?<p className="mt-1 text-cyanGlow">Recibido realmente: {formatInventoryQuantity(Number(line.base_quantity),unit,precision)} · Aplicado a solicitud: {formatInventoryQuantity(applied,unit,precision)}{excess>0?` · Excedente: ${formatInventoryQuantity(excess,unit,precision)}`:''}</p>:null}<p className="mt-1">Costo por presentación: {line.actual_package_cost == null ? 'Sin registrar' : money(line.actual_package_cost)} · Total: {line.line_total_cost == null ? 'Sin registrar' : money(line.line_total_cost)} · Por unidad base: {line.base_unit_cost == null ? 'Sin registrar' : money(line.base_unit_cost)}</p></div>;})}</div></article>) : <StateCard title="Sin recepciones">No hay entradas en esta página.</StateCard>}<PageNavigation page={page} hasMore={hasMore} loading={loading} onPrevious={()=>setPage((current)=>Math.max(current-1,0))} onNext={next}/></div>:null}
  </section>;
}

function RequestsTab({ data, area, busy, onCreate, onRun, refreshVersion }: { data: InventoryData; area: InventoryArea | null; busy: boolean; onCreate: () => void; onRun: (payload: Record<string, unknown>, message: string) => Promise<void>; refreshVersion: number }) {
  const pendingStatuses=['sent','partially_approved','approved','partially_received'];
  const [amounts,setAmounts]=useState<Record<string,string>>({}); const [rows,setRows]=useState<InventorySubmission[]>([]); const [hasMore,setHasMore]=useState(false); const [loading,setLoading]=useState(true); const [pageError,setPageError]=useState<string|null>(null); const [scope,setScope]=useState<'pending'|'all'>('pending'); const [kind,setKind]=useState<'all'|InventorySubmissionKind>('all'); const [status,setStatus]=useState('all'); const [areaFilter,setAreaFilter]=useState<'all'|InventoryArea>(area ?? 'all'); const [cursors,setCursors]=useState<Array<InventoryCursor|null>>([null]); const [page,setPage]=useState(0);
  useEffect(()=>{let active=true;setLoading(true);setPageError(null);const requestedStatus=status==='all'?(scope==='pending'?'pending':null):(scope==='pending'?`pending_${status}`:status);void loadInventorySubmissionsPage(kind==='all'?null:kind,requestedStatus,areaFilter==='all'?null:areaFilter,cursors[page]).then((result)=>{if(active){setRows(result.rows);setHasMore(result.has_more);}}).catch((reason)=>{if(active)setPageError(reason instanceof Error?reason.message:'No se pudieron cargar las solicitudes.');}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[scope,kind,status,areaFilter,page,cursors,refreshVersion]);
  const resetFilter=(nextKind:'all'|InventorySubmissionKind,nextStatus:string,nextArea:'all'|InventoryArea=areaFilter)=>{setKind(nextKind);setStatus(nextStatus);setAreaFilter(nextArea);setCursors([null]);setPage(0);};
  const changeScope=(nextScope:'pending'|'all')=>{setScope(nextScope);if(nextScope==='pending'&&status!=='all'&&!pendingStatuses.includes(status))setStatus('all');setCursors([null]);setPage(0);};
  const review = (entry: InventorySubmission, reviewStatus: 'approved'|'partially_approved'|'rejected') => { const lines=entry.lines.map((line)=>({line_id:line.id,approved_quantity:reviewStatus==='rejected'?0:Number(amounts[line.id]??line.requested_quantity??line.observed_quantity??0)})); return onRun({action:'review_submission',submission_id:entry.id,status:reviewStatus,notes:reviewStatus==='rejected'?'Rechazada desde Inventario':'Revisada desde Inventario',lines},reviewStatus==='rejected'?'Solicitud rechazada.':'Solicitud revisada.'); };
  const next=()=>{const last=rows[rows.length-1];if(!last)return;setCursors((current)=>[...current.slice(0,page+1),{timestamp:last.created_at,id:last.id}]);setPage((current)=>current+1);};
  return <section className="mt-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className={sectionTitle}>Solicitudes, conteos y daños</h2><p className={sectionCopy}>20 registros por página. Los filtros se resuelven en PostgreSQL.</p></div><button className={primaryButton} onClick={onCreate}>Nuevo reporte</button></div>
    {area?<p className="mt-4 rounded-[0.9rem] border border-cyanGlow/20 bg-cyanGlow/[0.06] px-4 py-3 text-sm text-mist">Vista operativa de {inventoryAreaName(data.areas,area)}: solo se consultan reportes autorizados para tu área.</p>:null}
    <div className="mt-4 grid gap-3 rounded-[1rem] border border-white/10 bg-black/15 p-4 sm:grid-cols-2 xl:grid-cols-4"><Field label="Vista"><select className={inputClass} value={scope} onChange={(event)=>changeScope(event.target.value as 'pending'|'all')}><option value="pending">Pendientes</option><option value="all">Todos</option></select></Field><Field label="Tipo"><select className={inputClass} value={kind} onChange={(event)=>resetFilter(event.target.value as 'all'|InventorySubmissionKind,status)}><option value="all">Todos</option><option value="replenishment">Reposición</option><option value="count">Conteo</option><option value="damage">Daño</option></select></Field><Field label="Estado"><select className={inputClass} value={status} onChange={(event)=>resetFilter(kind,event.target.value)}><option value="all">{scope==='pending'?'Todos los pendientes':'Todos'}</option>{Object.entries(inventoryStatusLabels).filter(([value])=>scope==='all'||pendingStatuses.includes(value)).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></Field><Field label="Área"><select className={inputClass} value={areaFilter} disabled={Boolean(area)} onChange={(event)=>resetFilter(kind,status,event.target.value as 'all'|InventoryArea)}><option value="all">Todas</option>{data.areas.filter((entry)=>entry.active).map((entry)=><option key={entry.code} value={entry.code}>{entry.name}</option>)}</select></Field></div>
    {pageError?<PageError message={pageError}/>:null}{loading?<p className="mt-5 text-sm text-cyanGlow">Cargando solicitudes…</p>:null}
    {!loading&&!pageError?<div className="mt-5 space-y-4">{rows.map((entry)=><article key={entry.id} className={`${card} relative overflow-hidden`}><InventorySubmissionStage kind={entry.kind} status={entry.status}/><div className="flex flex-wrap justify-between gap-3"><div><p className="font-semibold text-ivory">{submissionKindLabels[entry.kind]} · {inventoryAreaName(data.areas,entry.area)}</p><p className="mt-1 text-sm text-mist">{dateTime(entry.created_at)} · {entry.created_by}</p></div><InventoryStatusBadge status={entry.status}/></div><div className="mt-4 space-y-2">{entry.lines.map((line)=><SubmissionLineDetails key={line.id} data={data} entry={entry} line={line} amount={amounts[line.id]} canEdit={data.can_manage&&['sent','partially_approved'].includes(entry.status)} onAmountChange={(value)=>setAmounts((current)=>({...current,[line.id]:value}))}/>)}</div>{entry.notes?<p className="mt-3 text-sm text-mist">{entry.notes}</p>:null}{entry.status==='draft'?<div className="mt-4"><button disabled={busy} className={primaryButton} onClick={()=>void onRun({action:'send_submission',submission_id:entry.id},'Reporte enviado para revisión.')}>Enviar borrador</button></div>:null}{data.can_manage&&['sent','partially_approved'].includes(entry.status)?<div className="mt-4 flex flex-wrap gap-2"><button disabled={busy} className={primaryButton} onClick={()=>void review(entry,'approved')}>Aprobar</button>{entry.kind==='replenishment'?<button disabled={busy} className={ghostButton} onClick={()=>void review(entry,'partially_approved')}>Aprobar parcial</button>:null}<button disabled={busy} className={dangerButton} onClick={()=>void review(entry,'rejected')}>Rechazar</button></div>:null}</article>)}{!rows.length?<StateCard title="Sin reportes">No hay registros con estos filtros.</StateCard>:null}<PageNavigation page={page} hasMore={hasMore} loading={loading} onPrevious={()=>setPage((current)=>Math.max(current-1,0))} onNext={next}/></div>:null}
  </section>;
}
function SubmissionLineDetails({ data, entry, line, amount, canEdit, onAmountChange }: { data: InventoryData; entry: InventorySubmission; line: InventorySubmission['lines'][number]; amount: string | undefined; canEdit: boolean; onAmountChange: (value: string) => void }) {
  const parsedNotes = parseInventorySubmissionLineNotes(line.notes);
  const item = data.items.find((candidate) => candidate.id === line.item_id);
  const requested = Number(line.requested_quantity ?? 0);
  return <div className="grid gap-3 rounded-[0.9rem] bg-black/20 p-3 text-sm sm:grid-cols-[minmax(0,1fr)_auto_auto]">
    <div><strong className="text-ivory">{line.item_name}</strong>{entry.kind === 'replenishment' && parsedNotes.presentation ? <div className="mt-1 text-mist"><p>Solicitado: {parsedNotes.presentation.package_quantity} × {parsedNotes.presentation.presentation_name}</p><p>Equivale a: {item ? formatInventoryQuantity(requested, item.base_unit, item.precision_scale) : requested}</p></div> : null}<p className="mt-1 text-mist">{parsedNotes.notes || 'Sin nota'}</p></div>
    {entry.kind === 'count' ? <p className="text-mist">Observado: {line.observed_quantity}</p> : !parsedNotes.presentation ? <p className="text-mist">Cantidad: {item ? formatInventoryQuantity(requested, item.base_unit, item.precision_scale) : line.requested_quantity}</p> : null}
    {canEdit ? <input aria-label={`Cantidad aprobada ${line.item_name}`} className={`${inputClass} w-32`} value={amount ?? String(line.requested_quantity ?? line.observed_quantity ?? 0)} onChange={(event) => onAmountChange(event.target.value)} /> : <p className="text-mist">Aprobado: {line.approved_quantity ?? 'Pendiente'}</p>}
  </div>;
}

function HistoryTab({ data, refreshVersion }: { data: InventoryData; refreshVersion: number }) {
  const [month,setMonth]=useState(inventoryMonthValue()); const [rows,setRows]=useState<InventoryData['movements']>([]); const [hasMore,setHasMore]=useState(false); const [loading,setLoading]=useState(true); const [exporting,setExporting]=useState(false); const [pageError,setPageError]=useState<string|null>(null); const [cursors,setCursors]=useState<Array<InventoryCursor|null>>([null]); const [page,setPage]=useState(0);
  useEffect(()=>{let active=true;setLoading(true);setPageError(null);void loadInventoryMovementsPage(month,cursors[page]).then((result)=>{if(active){setRows(result.rows);setHasMore(result.has_more);}}).catch((reason)=>{if(active)setPageError(reason instanceof Error?reason.message:'No se pudo cargar el historial.');}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[month,page,cursors,refreshVersion]);
  const changeMonth=(value:string)=>{setMonth(value);setCursors([null]);setPage(0);}; const next=()=>{const last=rows[rows.length-1];if(!last)return;setCursors((current)=>[...current.slice(0,page+1),{timestamp:last.occurred_at,id:last.id}]);setPage((current)=>current+1);};
  const exportCsv=async()=>{setExporting(true);setPageError(null);try{const allRows=await loadInventoryMovementExport(month);downloadInventoryCsv(`inventario-${month}.csv`,inventoryMovementCsv(allRows));}catch(reason){setPageError(reason instanceof Error?reason.message:'No se pudo exportar el historial.');}finally{setExporting(false);}};
  return <section className="mt-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className={sectionTitle}>Historial inmutable</h2><p className={sectionCopy}>50 movimientos por página. El mes y la exportación completa se resuelven en PostgreSQL.</p></div><button className={ghostButton} disabled={exporting} onClick={()=>void exportCsv()}>{exporting?'Exportando…':'Exportar CSV del mes'}</button></div>
    <div className="mt-4 max-w-xs"><Field label="Mes"><input className={inputClass} type="month" value={month} onChange={(event)=>changeMonth(event.target.value)}/></Field></div>{pageError?<PageError message={pageError}/>:null}{loading?<p className="mt-5 text-sm text-cyanGlow">Cargando movimientos…</p>:null}
    {!loading&&!pageError?<><div className="mt-5 overflow-x-auto rounded-[1.1rem] border border-white/10"><table className="min-w-full text-left text-sm"><thead className="bg-white/[0.05] text-xs uppercase tracking-[0.13em] text-mist"><tr><th className="p-3">Fecha</th><th className="p-3">Artículo</th><th className="p-3">Movimiento</th><th className="p-3">Cantidad</th><th className="p-3">Costo rastreado</th><th className="p-3">Responsable</th><th className="p-3">Referencia</th></tr></thead><tbody>{rows.map((row)=><tr key={row.id} className="border-t border-white/8"><td className="p-3 text-mist">{dateTime(row.occurred_at)}</td><td className="p-3 text-ivory">{row.item_name}</td><td className="p-3"><span className="text-ivory">{movementLabels[row.movement_type]??row.movement_type}</span><br/><span className="text-xs text-mist">{row.reason}</span></td><td className={`p-3 font-semibold ${Number(row.quantity_delta)<0?'text-rose-200':'text-emerald-200'}`}>{Number(row.quantity_delta)>0?'+':''}{formatInventoryQuantity(Number(row.quantity_delta),row.base_unit_snapshot)}</td><td className="p-3 text-mist">{row.tracked_value_delta==null?'Sin costo conocido':money(Math.abs(Number(row.tracked_value_delta)))}</td><td className="p-3 text-mist">{row.actor}</td><td className="p-3 text-xs text-mist">{row.sales_session_id||row.order_item_id||'Operación interna'}</td></tr>)}</tbody></table></div>{!rows.length?<StateCard title="Sin movimientos">No hay movimientos en el mes seleccionado.</StateCard>:null}<PageNavigation page={page} hasMore={hasMore} loading={loading} onPrevious={()=>setPage((current)=>Math.max(current-1,0))} onNext={next}/></>:null}
  </section>;
}
function MenuRecipesTab({ data, onConfigure }: { data: InventoryData; onConfigure: (menuKey: string) => void }) {
  const [search,setSearch]=useState('');
  const [status,setStatus]=useState<InventoryMenuRecipeStatus|'all'>('all');
  const rows=useMemo(()=>buildInventoryMenuRecipeRows(data.menu_items,data.recipes,data.items),[data.items,data.menu_items,data.recipes]);
  const normalizedSearch=search.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es-CO');
  const filtered=rows.filter((row)=>(!normalizedSearch||row.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es-CO').includes(normalizedSearch))&&(status==='all'||row.status===status));
  const configured=rows.filter((row)=>row.status==='configured').length;
  const missing=rows.filter((row)=>row.status==='missing').length;
  const partial=rows.filter((row)=>row.status==='partial').length;
  return <section className="mt-5">
    <div><h2 className={sectionTitle}>Consumo del menú</h2><p className={sectionCopy}>Recetas, costo vigente por última compra real y margen bruto estimado de cada producto.</p></div>
    <p className="mt-4 text-sm text-mist"><strong className="text-ivory">{rows.length}</strong> productos · <strong className="text-emerald-200">{configured}</strong> configurados · <strong className="text-mist">{missing}</strong> sin receta · <strong className="text-amber-100">{partial}</strong> con costo parcial</p>
    <div className="mt-5 grid gap-3 rounded-[1.1rem] border border-white/10 bg-white/[0.025] p-4 md:grid-cols-2"><Field label="Buscar producto"><input aria-label="Buscar producto del menú" className={inputClass} value={search} onChange={(event)=>setSearch(event.target.value)} placeholder="Nombre del producto" /></Field><Field label="Estado de receta"><select aria-label="Filtrar recetas por estado" className={inputClass} value={status} onChange={(event)=>setStatus(event.target.value as InventoryMenuRecipeStatus|'all')}><option value="all">Todos</option><option value="missing">Sin receta</option><option value="configured">Configurada</option><option value="partial">Costo parcial</option></select></Field></div>
    <>
      <div className="mt-5 hidden overflow-x-auto rounded-[1.1rem] border border-white/10 md:block"><table className="w-full min-w-[68rem] text-left text-sm"><thead className="bg-white/[0.05] text-xs uppercase tracking-[0.1em] text-mist"><tr><th className="p-3">Producto</th><th className="p-3">Receta</th><th className="p-3">Ingredientes</th><th className="p-3">Costo calculado</th><th className="p-3">Precio venta</th><th className="p-3">Margen estimado</th><th className="p-3">Acción</th></tr></thead><tbody>{filtered.map((row)=><tr key={row.source_key} className="border-t border-white/8 align-top"><td className="p-3 font-semibold text-ivory">{row.name}</td><td className="p-3"><InventoryRecipeStatusBadge status={row.status}/></td><td className="max-w-xs p-3 text-mist">{inventoryRecipeIngredients(row.components)}</td><td className="p-3 text-mist">{inventoryRecipeCost(row.status,row.calculated_cost)}</td><td className="p-3 text-ivory">{row.price==null?'—':money(row.price)}</td><td className="p-3 text-mist">{row.estimated_margin==null?'—':`${new Intl.NumberFormat('es-CO',{maximumFractionDigits:1}).format(row.estimated_margin)}%`}</td><td className="p-3"><button className={ghostButton} onClick={()=>onConfigure(row.source_key)}>Configurar</button></td></tr>)}</tbody></table></div>
      <div className="mt-5 grid gap-3 md:hidden">{filtered.map((row)=><article key={row.source_key} className={card}><div className="flex items-start justify-between gap-3"><h3 className="font-semibold text-ivory">{row.name}</h3><InventoryRecipeStatusBadge status={row.status}/></div><dl className="mt-4 grid grid-cols-2 gap-3 text-sm"><div className="col-span-2"><dt className="text-xs uppercase tracking-[0.12em] text-mist">Ingredientes</dt><dd className="mt-1 text-ivory">{inventoryRecipeIngredients(row.components)}</dd></div><div><dt className="text-xs uppercase tracking-[0.12em] text-mist">Costo</dt><dd className="mt-1 text-ivory">{inventoryRecipeCost(row.status,row.calculated_cost)}</dd></div><div><dt className="text-xs uppercase tracking-[0.12em] text-mist">Precio</dt><dd className="mt-1 text-ivory">{row.price==null?'—':money(row.price)}</dd></div><div><dt className="text-xs uppercase tracking-[0.12em] text-mist">Margen estimado</dt><dd className="mt-1 text-ivory">{row.estimated_margin==null?'—':`${new Intl.NumberFormat('es-CO',{maximumFractionDigits:1}).format(row.estimated_margin)}%`}</dd></div></dl><button className={`${ghostButton} mt-5`} onClick={()=>onConfigure(row.source_key)}>Configurar</button></article>)}</div>
      {!filtered.length?<StateCard title="Sin resultados">No hay productos que coincidan con la búsqueda y el estado seleccionados.</StateCard>:null}
    </>
  </section>;
}

function InventoryRecipeStatusBadge({status}:{status:InventoryMenuRecipeStatus}) { const styles={missing:'border-white/12 bg-white/[0.05] text-mist',configured:'border-emerald-300/25 bg-emerald-300/10 text-emerald-100',partial:'border-amberGlow/25 bg-amberGlow/10 text-amber-100'}; const labels={missing:'Sin receta',configured:'Configurada',partial:'Costo parcial'}; return <span className={`inline-flex whitespace-nowrap rounded-full border px-2.5 py-1 text-[0.68rem] font-semibold ${styles[status]}`}>{labels[status]}</span>; }
function inventoryRecipeIngredients(components:Array<{name:string;quantity_base:number|null;unit:InventoryUnit}>) { if(!components.length)return '—'; const visible=components.slice(0,4).map((component)=>component.quantity_base==null?component.name:`${component.name} ${formatInventoryQuantity(component.quantity_base,component.unit)}`); return `${visible.join(', ')}${components.length>4?` +${components.length-4}`:''}`; }
function inventoryRecipeCost(status:InventoryMenuRecipeStatus,cost:number|null) { if(status==='missing')return '—'; if(status==='partial')return cost==null?'Parcial · sin costo conocido':`Parcial ${money(cost)}`; return cost==null?'—':money(cost); }

function ConfigurationTab({ data, onAction, onEditItem, onEditPresentation, onEditArea }: { data: InventoryData; onAction: (modal: Modal) => void; onEditItem: (item: InventoryItem) => void; onEditPresentation: (presentation: InventoryData['presentations'][number]) => void; onEditArea: (area: InventoryAreaDefinition) => void }) {
  const [search,setSearch]=useState(''); const [area,setArea]=useState<InventoryArea|'all'>('all'); const [usageType,setUsageType]=useState<InventoryUsageType|'all'>('all'); const [active,setActive]=useState<'all'|'active'|'inactive'>('all');
  const filteredItems=data.items.filter((item)=>inventoryItemMatchesSearch(item,search)&&(area==='all'||item.areas.includes(area))&&(usageType==='all'||item.usage_type===usageType)&&(active==='all'||item.active===(active==='active')));
  return <section className="mt-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className={sectionTitle}>Configuración administrativa</h2><p className={sectionCopy}>Administra artículos, áreas responsables, unidades base y presentaciones de compra.</p></div><div className="flex flex-wrap gap-2"><button className={ghostButton} onClick={() => XLSX.writeFile(createInventoryTemplateWorkbook(), 'plantilla-inventario-zafiro.xlsx')}>Descargar plantilla</button><button className={primaryButton} onClick={() => onAction('import')}>Importar inventario</button></div></div>
    <details className="group mt-6 rounded-[1.1rem] border border-white/10 bg-white/[0.025]">
      <summary className="flex cursor-pointer list-none items-center justify-between gap-4 p-5 [&::-webkit-details-marker]:hidden"><div><h3 className="font-display text-2xl text-ivory">Áreas de inventario</h3><p className="mt-2 text-sm text-mist">Organizan artículos y reportes. Crear un área no crea roles ni espacios del POS.</p></div><span className="inline-flex shrink-0 items-center gap-2 text-xs font-semibold uppercase tracking-[0.15em] text-cyanGlow"><span className="group-open:hidden">Mostrar</span><span className="hidden group-open:inline">Ocultar</span><span aria-hidden="true" className="flex h-4 w-4 items-center justify-center text-sm leading-none transition group-open:rotate-180">▾</span></span></summary>
      <div className="border-t border-white/10 p-5"><div className="flex justify-end"><button className={primaryButton} onClick={()=>onAction('area')}>Crear área</button></div><div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{data.areas.map((area)=><article key={area.code} className={card}><div className="flex items-start justify-between gap-3"><div><p className="font-semibold text-ivory">{area.name}</p><p className="mt-1 font-mono text-xs text-mist">{area.code}</p></div><span className={`rounded-full border px-2.5 py-1 text-[0.62rem] uppercase tracking-[0.12em] ${area.active?'border-emerald-300/25 bg-emerald-300/10 text-emerald-100':'border-white/10 bg-white/[0.04] text-mist'}`}>{area.active?'Activa':'Inactiva'}</span></div><p className="mt-3 text-sm text-mist">{area.system_protected?'Área operativa del POS':'Área de inventario'}</p><button className={`${ghostButton} mt-4`} onClick={()=>onEditArea(area)}>Editar</button></article>)}</div></div>
    </details>
    <div className="mt-5 grid gap-4 md:grid-cols-2"><ActionCard title="Artículos" copy="Unidad base, áreas, mínimos y objetivos." action="Crear artículo" onClick={() => onAction('item')} /><ActionCard title="Presentaciones" copy="Varios paquetes o envases por artículo." action="Crear presentación" onClick={() => onAction('presentation')} /></div>
    <p className="mt-4 text-sm text-mist">Las recetas y sus costos se administran desde la pestaña <strong className="text-ivory">Consumo del menú</strong>.</p>
    <div className="mt-6 grid gap-3 rounded-[1.1rem] border border-white/10 bg-white/[0.025] p-4 sm:grid-cols-2 xl:grid-cols-4"><Field label="Buscar artículos y presentaciones"><input aria-label="Buscar artículos configurados" className={inputClass} value={search} onChange={(event)=>setSearch(event.target.value)} placeholder="Nombre o código" /></Field><Field label="Área"><select aria-label="Filtrar configuración por área" className={inputClass} value={area} onChange={(event)=>setArea(event.target.value as InventoryArea|'all')}><option value="all">Todas</option>{data.areas.filter((entry)=>entry.active).map((entry)=><option key={entry.code} value={entry.code}>{entry.name}</option>)}</select></Field><Field label="Tipo"><select aria-label="Filtrar configuración por tipo" className={inputClass} value={usageType} onChange={(event)=>setUsageType(event.target.value as InventoryUsageType|'all')}><option value="all">Todos</option><option value="consumable">Consumibles</option><option value="operational">Operativos</option></select></Field><Field label="Estado"><select aria-label="Filtrar configuración por estado" className={inputClass} value={active} onChange={(event)=>setActive(event.target.value as 'all'|'active'|'inactive')}><option value="all">Todos</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select></Field></div>
    <div className="mt-4 grid gap-3 md:grid-cols-2">{filteredItems.map((item) => <div key={item.id} className={card}><div className="flex items-start justify-between gap-3"><div><p className="font-semibold text-ivory">{item.name}</p><p className="mt-1 text-sm text-mist">Base: {inventoryUnitLabels[item.base_unit]} · {item.areas.map((code)=>inventoryAreaName(data.areas,code)).join(' · ')}</p></div><button className={ghostButton} onClick={() => onEditItem(item)}>Editar</button></div><div className="mt-4 space-y-2">{data.presentations.filter((row) => row.item_id === item.id).map((row) => <button key={row.id} onClick={() => onEditPresentation(row)} className="block w-full rounded-[0.8rem] border border-white/8 bg-black/15 px-3 py-2 text-left text-sm text-mist hover:border-cyanGlow/25">{row.name} · {row.content_per_package} {inventoryUnitLabels[row.content_unit]} · Costo sugerido: {row.suggested_package_cost == null ? 'Sin registrar' : money(row.suggested_package_cost)} {row.active ? '' : '· Inactiva'}</button>)}{!data.presentations.some((row) => row.item_id === item.id) ? <p className="text-sm text-mist">Sin presentaciones</p> : null}</div></div>)}</div>{!filteredItems.length?<StateCard title="Sin resultados">No hay artículos configurados que coincidan con la búsqueda.</StateCard>:null}
  </section>;
}

function ReceiveDialog({ data, initialItemId, pendingRefreshVersion, busy, onClose, onSave }: DialogProps & { data: InventoryData; initialItemId: string | null; pendingRefreshVersion: number }) {
  const lockedItem=initialItemId?data.items.find((item)=>item.id===initialItemId):undefined;
  const [lines,setLines]=useState<InventoryPurchaseDraftLine[]>(()=>[createInventoryPurchaseLine(data,initialItemId??undefined)]);
  const [pendingSubmissions,setPendingSubmissions]=useState<InventorySubmission[]|null>(null);
  const [pendingLoading,setPendingLoading]=useState(true); const [pendingError,setPendingError]=useState<string|null>(null); const [submissionNotice,setSubmissionNotice]=useState<string|null>(null);
  const [cashData,setCashData]=useState<CashData|null>(null); const [cashError,setCashError]=useState<string|null>(null);
  const [supplier,setSupplier]=useState(''); const [documentRef,setDocumentRef]=useState(''); const [notes,setNotes]=useState('');
  const [paymentOrigin,setPaymentOrigin]=useState<'register'|'business'|'owner'|'unpaid'>('unpaid'); const [method,setMethod]=useState<keyof typeof methods>('bank_transfer');
  useEffect(()=>{let active=true;void loadCash().then((cash)=>{if(active)setCashData(cash);}).catch((reason)=>{if(active)setCashError(reason instanceof Error?reason.message:'No se pudo consultar la caja.');});return()=>{active=false;};},[]);
  useEffect(()=>{let active=true;setPendingLoading(true);setPendingError(null);void loadInventoryPendingReplenishments().then((pending)=>{if(active)setPendingSubmissions(pending);}).catch((reason)=>{if(active)setPendingError(reason instanceof Error?reason.message:'No se pudieron cargar las solicitudes aprobadas.');}).finally(()=>{if(active)setPendingLoading(false);});return()=>{active=false;};},[pendingRefreshVersion]);
  const total=inventoryPurchaseTotal(data,lines); const activeSession=cashData?.sessions.find((session)=>session.status==='open'); const activeRegister=activeSession?cashData?.registers.find((register)=>register.sales_session_id===activeSession.id&&!register.closed_at):undefined;
  const paid=paymentOrigin!=='unpaid'; const valid=inventoryPurchaseLinesValid(data,lines)&&(!paid||total!=null&&total>0)&&(paymentOrigin!=='register'||Boolean(activeSession&&activeRegister));
  if(lockedItem&&!lockedItem.tracking_started_at)return <Dialog title="Registrar entrada" onClose={onClose}><div className="space-y-4"><p className="font-semibold text-ivory">{lockedItem.name}</p><div role="alert" className="rounded-[0.9rem] border border-amberGlow/30 bg-amberGlow/[0.08] p-4 text-sm text-amber-100">Primero registra el conteo inicial de este artículo. La restricción de recepción se mantiene hasta iniciar su seguimiento.</div><div className="flex justify-end"><button type="button" className={ghostButton} onClick={onClose}>Cerrar</button></div></div></Dialog>;
  const submit=(event:FormEvent)=>{event.preventDefault();if(!valid)return;void onSave({action:'purchase',source:'inventory',payment_origin:paymentOrigin,session:paymentOrigin==='register'?activeSession?.id:null,method:paymentOrigin==='register'?'cash':method,concept:'Compra de insumos',date:bogotaToday(),received_at:new Date().toISOString(),supplier,document_reference:documentRef,notes,total_cost:total,lines:buildInventoryPurchaseLines(data,lines)},paymentOrigin==='unpaid'?'Entrada guardada como compra pendiente de pago.':'Compra, gasto y entrada guardados una sola vez.');};
  return <Dialog title="Registrar entrada" onClose={onClose}><form onSubmit={submit} className="space-y-5">
    {pendingLoading?<p className="text-sm text-cyanGlow">Actualizando solicitudes pendientes…</p>:null}{submissionNotice?<p role="status" className="rounded-[0.8rem] border border-amberGlow/25 bg-amberGlow/[0.07] p-3 text-sm text-amber-100">{submissionNotice}</p>:null}
    <InventoryPurchaseLinesEditor data={data} lines={lines} setLines={setLines} lockedFirstItemId={initialItemId} pendingSubmissions={pendingSubmissions} pendingError={pendingError} onSubmissionNotice={setSubmissionNotice}/>
    <div className="rounded-[1rem] border border-cyanGlow/20 bg-cyanGlow/[0.06] p-4"><p className="text-sm text-mist">Total productos</p><p className="mt-1 text-xl text-ivory">{total==null?'Completa los costos':money(total)}</p></div>
    <Field label="¿Cómo se pagó esta compra?"><select aria-label="Origen de pago de la compra" className={inputClass} value={paymentOrigin} onChange={(event)=>setPaymentOrigin(event.target.value as typeof paymentOrigin)}><option value="register">Caja del local</option><option value="business">Fondos del negocio fuera de caja</option><option value="owner">Dinero de un propietario</option><option value="unpaid">Solo registrar inventario / pago pendiente</option></select></Field>
    {paid&&paymentOrigin!=='register'?<Field label="Método de pago"><select className={inputClass} value={method} onChange={(event)=>setMethod(event.target.value as keyof typeof methods)}>{Object.entries(methods).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></Field>:null}
    {paymentOrigin==='register'?<p className={`rounded-[0.8rem] border p-3 text-sm ${activeSession&&activeRegister?'border-emerald-300/20 bg-emerald-300/[0.06] text-emerald-100':'border-rose-300/25 bg-rose-300/[0.08] text-rose-100'}`}>{activeSession&&activeRegister?`Se descontará del efectivo de ${activeSession.session_label}.`:'No hay una jornada abierta con caja registrada. Elige otro origen o completa la caja.'}</p>:paymentOrigin==='unpaid'?<p className="text-sm text-mist">Se actualizará inventario sin crear un gasto pagado.</p>:<p className="text-sm text-mist">Se registrará el gasto con origen “{origins[paymentOrigin]}” sin disminuir el efectivo físico de caja.</p>}
    {cashError&&paymentOrigin==='register'?<PageError message={cashError}/>:null}
    <div className="grid gap-3 sm:grid-cols-2"><Field label="Proveedor (opcional)"><input className={inputClass} value={supplier} onChange={(event)=>setSupplier(event.target.value)}/></Field><Field label="Documento (opcional)"><input className={inputClass} value={documentRef} onChange={(event)=>setDocumentRef(event.target.value)}/></Field></div>
    <Field label="Observación"><textarea className={inputClass} rows={2} value={notes} onChange={(event)=>setNotes(event.target.value)}/></Field>
    <DialogButtons busy={busy} onClose={onClose} label={paid?'Guardar compra y entrada':'Guardar entrada'} disabled={!valid}/>
  </form></Dialog>;
}

function SubmissionDialog({ data, area, busy, onClose, onSave }: DialogProps & { data: InventoryData; area: PosInventoryArea | null }) {
  const activeAreas=data.areas.filter((entry)=>entry.active); const initialArea=area ?? activeAreas[0]?.code ?? '';
  const [kind,setKind]=useState<InventorySubmissionKind>('replenishment'); const [submissionStatus,setSubmissionStatus]=useState<'draft'|'sent'>('sent'); const [selectedArea,setArea]=useState<InventoryArea>(initialArea); const available=filterInventoryItemsByArea(data.items,selectedArea); const [itemId,setItemId]=useState(available[0]?.id??''); const [itemSearch,setItemSearch]=useState(''); const [quantity,setQuantity]=useState(''); const [notes,setNotes]=useState('');
  useEffect(()=>{const next=getInventoryItemSearchSelection(available,itemId,itemSearch).selectedItemId;if(next!==itemId)setItemId(next);},[selectedArea,data,itemId,itemSearch]);
  const selection=getInventoryItemSearchSelection(available,itemId,itemSearch);
  const changeItemSearch=(value:string)=>{const next=getInventoryItemSearchSelection(available,itemId,value);setItemSearch(value);setItemId(next.selectedItemId);};
  return <Dialog title="Nuevo reporte de inventario" onClose={onClose}><form className="space-y-4" onSubmit={(event)=>{event.preventDefault(); void onSave({action:'submit',kind,area:selectedArea,status:submissionStatus,notes,lines:[{item_id:itemId,[kind==='count'?'observed_quantity':'requested_quantity']:Number(quantity),notes}]},submissionStatus==='draft'?'Borrador guardado.':'Reporte enviado para revisión.');}}><Field label="Tipo"><select className={inputClass} value={kind} onChange={(e)=>setKind(e.target.value as InventorySubmissionKind)}><option value="replenishment">Solicitud de reposición</option><option value="count">Conteo físico</option><option value="damage">Daño o pérdida</option></select></Field>{!area?<Field label="Área"><select className={inputClass} value={selectedArea} onChange={(e)=>{setItemSearch('');setArea(e.target.value as InventoryArea);}}>{activeAreas.map((entry)=><option key={entry.code} value={entry.code}>{entry.name}</option>)}</select></Field>:null}<Field label="Buscar artículo"><input aria-label="Buscar artículo para reporte" className={inputClass} value={itemSearch} onChange={(event)=>changeItemSearch(event.target.value)} placeholder="Nombre o código" /></Field><Field label="Artículo"><select className={inputClass} required value={itemId} disabled={!selection.options.length} onChange={(e)=>setItemId(e.target.value)}>{selection.options.length?selection.options.map((item)=><option key={item.id} value={item.id}>{item.name} · {formatInventoryQuantity(item.balance,item.base_unit)}</option>):<option value="">Sin artículos coincidentes</option>}</select></Field><Field label={kind==='count'?'Cantidad física observada':'Cantidad'}><input className={inputClass} type="number" min="0" step="0.001" required value={quantity} onChange={(e)=>setQuantity(e.target.value)} /></Field><Field label="Notas"><textarea className={inputClass} rows={3} value={notes} onChange={(e)=>setNotes(e.target.value)} /></Field><Field label="Guardar como"><select className={inputClass} value={submissionStatus} onChange={(e)=>setSubmissionStatus(e.target.value as 'draft'|'sent')}><option value="sent">Enviar a revisión</option><option value="draft">Guardar borrador</option></select></Field><p className="text-sm text-mist">Enviar este reporte no cambia las existencias.</p><DialogButtons busy={busy} onClose={onClose} label={submissionStatus==='draft'?'Guardar borrador':'Enviar reporte'} disabled={!selectedArea||!itemId||quantity===''}/></form></Dialog>;
}

function ItemDialog({ data,initial,busy,onClose,onSave,onDelete }: DialogProps & { data: InventoryData; initial: InventoryItem | null; onDelete:(id:string)=>void }) { const [name,setName]=useState(initial?.name??''); const [usageType,setUsageType]=useState<InventoryUsageType>(initial?.usage_type??'consumable'); const [unit,setUnit]=useState<InventoryUnit>(initial?.base_unit??'unit'); const [minimum,setMinimum]=useState(initial?.minimum_quantity==null?'':String(initial.minimum_quantity)); const [target,setTarget]=useState(initial?.target_quantity==null?'':String(initial.target_quantity)); const defaultArea=data.areas.find((entry)=>entry.active)?.code; const [areas,setAreas]=useState<InventoryArea[]>(initial?.areas??(defaultArea?[defaultArea]:[])); const selectableAreas=data.areas.filter((entry)=>entry.active||initial?.areas.includes(entry.code)); return <Dialog title={initial?'Editar artículo':'Crear artículo'} onClose={onClose}><form className="space-y-4" onSubmit={(e)=>{e.preventDefault();void onSave({action:'save_item',id:initial?.id,name,base_unit:unit,active:initial?.active??true,precision_scale:unit==='unit'?0:3,minimum_quantity:minimum||null,target_quantity:target||null,usage_type:usageType,areas},initial?'Artículo actualizado.':'Artículo creado. Registra su conteo inicial para activar seguimiento.');}}><Field label="Nombre"><input className={inputClass} required value={name} onChange={(e)=>setName(e.target.value)}/></Field><Field label="Unidad base"><select disabled={Boolean(initial)} className={inputClass} value={unit} onChange={(e)=>setUnit(e.target.value as InventoryUnit)}><option value="unit">Unidad</option><option value="gram">Gramo</option><option value="milliliter">Mililitro</option></select></Field><Field label="Tipo de uso"><select className={inputClass} value={usageType} onChange={(event)=>setUsageType(event.target.value as InventoryUsageType)}><option value="consumable">Consumible</option><option value="operational">Operativo</option></select><p className="mt-2 text-xs leading-5 text-mist">{usageType==='consumable'?'Puede participar en recetas y consumos automáticos.':'Se controla por existencias, conteos, daños y reposición, pero no se consume por ventas.'}</p></Field><div className="grid grid-cols-2 gap-3"><Field label="Mínimo"><input className={inputClass} type="number" min="0" step="0.001" value={minimum} onChange={(e)=>setMinimum(e.target.value)}/></Field><Field label="Objetivo"><input className={inputClass} type="number" min="0" step="0.001" value={target} onChange={(e)=>setTarget(e.target.value)}/></Field></div><Field label="Áreas responsables"><div className="grid gap-3 sm:grid-cols-2">{selectableAreas.map((area)=><label key={area.code} className={`flex gap-2 text-sm ${area.active?'text-mist':'text-mist/60'}`}><input type="checkbox" checked={areas.includes(area.code)} disabled={!area.active} onChange={(e)=>setAreas((current)=>e.target.checked?[...new Set([...current,area.code])]:current.filter((value)=>value!==area.code))}/>{area.name}{area.active?'':' (inactiva, se conserva)'}</label>)}</div></Field>{initial?<button type="button" className={dangerButton} disabled={busy} onClick={()=>onDelete(initial.id)}>Eliminar artículo</button>:null}<DialogButtons busy={busy} onClose={onClose} label={initial?'Guardar cambios':'Crear artículo'} disabled={!name.trim()||!areas.length}/></form></Dialog>; }

function AreaDialog({ initial,busy,onClose,onSave,onDelete }: DialogProps & { initial: InventoryAreaDefinition | null; onDelete:(code:string)=>void }) { const [name,setName]=useState(initial?.name??''); const [code,setCode]=useState(initial?.code??''); const [active,setActive]=useState(initial?.active??true); const normalizeCode=(value:string)=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,''); return <Dialog title={initial?'Editar área':'Crear área de inventario'} onClose={onClose}><form className="space-y-4" onSubmit={(event)=>{event.preventDefault();void onSave({action:'save_area',id:initial?.id,code:initial?.code??normalizeCode(code||name),name,active},initial?'Área actualizada.':'Área creada.');}}><Field label="Nombre"><input className={inputClass} required value={name} onChange={(event)=>{setName(event.target.value);if(!initial&&!code)setCode(normalizeCode(event.target.value));}} /></Field><Field label="Código estable"><input className={inputClass} required disabled={Boolean(initial)} value={code} onChange={(event)=>setCode(normalizeCode(event.target.value))} placeholder="ej. bodega" /></Field>{initial?<label className="flex items-center gap-3 text-sm text-mist"><input type="checkbox" checked={active} disabled={initial.system_protected} onChange={(event)=>setActive(event.target.checked)}/> Área activa{initial.system_protected?' (protegida por el POS)':''}</label>:null}<p className="text-sm text-mist">El código no podrá cambiarse después. El área organiza inventario; no crea roles ni pantallas del POS.</p>{initial&&!initial.system_protected?<button type="button" className={dangerButton} disabled={busy} onClick={()=>onDelete(initial.code)}>Eliminar área</button>:null}<DialogButtons busy={busy} onClose={onClose} label={initial?'Guardar cambios':'Crear área'} disabled={!name.trim()||!normalizeCode(code||name)}/></form></Dialog>; }

function PresentationDialog({ data,initial,busy,onClose,onSave,onDelete }: DialogProps & {data:InventoryData;initial:InventoryData['presentations'][number]|null;onDelete:(id:string)=>void}) {
  const [itemId,setItemId]=useState(initial?.item_id??data.items[0]?.id??'');
  const [itemSearch,setItemSearch]=useState('');
  const selection=getInventoryItemSearchSelection(data.items,itemId,itemSearch);
  const item=data.items.find((row)=>row.id===itemId);
  const [name,setName]=useState(initial?.name??'');
  const [content,setContent]=useState(initial?String(initial.content_per_package):'');
  const initialCost=inventoryMoneyInput(formatInventoryMoneyInput(initial?.suggested_package_cost));
  const [costDisplay,setCostDisplay]=useState(initialCost.display);
  const [costValue,setCostValue]=useState<number|null>(initialCost.value);
  const [validationError,setValidationError]=useState<string|null>(null);
  const changeItemSearch=(value:string)=>{
    const nextSelection=getInventoryItemSearchSelection(data.items,itemId,value);
    setItemSearch(value);
    setItemId(nextSelection.selectedItemId);
  };
  const save=(event:FormEvent)=>{event.preventDefault();const quantity=Number(content);if(!itemId||!item){setValidationError('Selecciona un artículo válido.');return;}if(!name.trim()){setValidationError('Escribe el nombre de la presentación.');return;}if(!Number.isFinite(quantity)||quantity<=0){setValidationError('Ingresa un contenido por paquete o envase mayor que cero.');return;}setValidationError(null);void onSave({action:'save_presentation',id:initial?.id,item_id:itemId,name:name.trim(),content_per_package:quantity,content_unit:item.base_unit,suggested_package_cost:costValue,active:initial?.active??true},initial?'Presentación actualizada; las recepciones anteriores conservan conversión y costos.':'Presentación creada.');};
  return <Dialog title={initial?'Editar presentación':'Crear presentación de compra'} onClose={onClose}><form className="space-y-4" noValidate onSubmit={save}>{initial?<Field label="Artículo"><div className={lockedValueClass}>{item?.name}</div></Field>:<><Field label="Buscar artículo"><input aria-label="Buscar artículo para presentación" className={inputClass} value={itemSearch} onChange={(event)=>changeItemSearch(event.target.value)} placeholder="Nombre o código" /></Field><Field label="Artículo"><select className={inputClass} value={itemId} disabled={!selection.options.length} onChange={(e)=>setItemId(e.target.value)}>{selection.options.length?selection.options.map((row)=><option value={row.id} key={row.id}>{row.name}</option>):<option value="">Sin artículos coincidentes</option>}</select></Field></>}<Field label="Nombre de la presentación"><input className={inputClass} value={name} onChange={(e)=>setName(e.target.value)} placeholder="Ej. Paquete x6 o Bolsa 200 g"/></Field><Field label={`Contenido por paquete/envase en ${item?inventoryUnitLabels[item.base_unit]:'unidad base'}`}><input className={inputClass} type="number" min="0.001" step="0.001" value={content} onChange={(e)=>setContent(e.target.value)}/></Field><Field label="Costo sugerido por paquete o envase (COP, opcional)"><input className={inputClass} inputMode="decimal" value={costDisplay} onChange={(e)=>{const formatted=inventoryMoneyInput(e.target.value);setCostDisplay(formatted.display);setCostValue(formatted.value);}} placeholder="7.000"/></Field><p className="text-sm text-mist">El costo sugerido solo precarga futuras recepciones. La unidad coincide con la base del artículo; no se convierten gramos y mililitros. Editar nombre, conversión o sugerencia no cambia recepciones históricas.</p>{validationError?<div role="alert" className="rounded-[0.9rem] border border-amberGlow/30 bg-amberGlow/[0.08] p-3 text-sm text-amber-100">{validationError}</div>:null}{initial?<button type="button" className={dangerButton} disabled={busy} onClick={()=>onDelete(initial.id)}>Eliminar presentación</button>:null}<DialogButtons busy={busy} onClose={onClose} label="Guardar presentación"/></form></Dialog>;
}

function RecipeDialog({ data,initialMenuKey,busy,onClose,onSave }: DialogProps & {data:InventoryData;initialMenuKey:string|null}) {
  const recipeItems=data.items.filter((item)=>(item.usage_type??'consumable')==='consumable'&&(item.areas.includes('bar')||item.areas.includes('kitchen')));
  const [menuKey,setMenuKey]=useState(initialMenuKey??data.menu_items[0]?.source_key??'');
  const [components,setComponents]=useState<Array<{item_id:string;controls_inventory:boolean;quantity_base:string}>>([{item_id:recipeItems[0]?.id??'',controls_inventory:true,quantity_base:''}]);
  const existing=data.recipes.filter((row)=>row.menu_item_source_key===menuKey&&row.active);
  const costSummary=summarizeInventoryRecipeCost(existing);
  useEffect(()=>{
    const saved=data.recipes.filter((row)=>row.menu_item_source_key===menuKey&&row.active);
    setComponents(saved.length?saved.map((row)=>({item_id:row.item_id,controls_inventory:row.controls_inventory??true,quantity_base:row.quantity_base==null?'':String(row.quantity_base)})):[{item_id:recipeItems[0]?.id??'',controls_inventory:true,quantity_base:''}]);
  },[menuKey,data]);
  const save=(event:FormEvent<HTMLFormElement>)=>{
    event.preventDefault();
    void onSave({
      action:'save_recipe',
      menu_item_source_key:menuKey,
      components:components.map((row)=>({item_id:row.item_id,controls_inventory:row.controls_inventory,quantity_base:row.quantity_base===''?null:Number(row.quantity_base)})),
    },'Consumo futuro del producto actualizado.');
  };
  const invalid=!menuKey||!components.length||components.some((row)=>!row.item_id||(row.controls_inventory&&Number(row.quantity_base)<=0)||(row.quantity_base!==''&&Number(row.quantity_base)<=0));
  return <Dialog title="Consumo por producto del menú" onClose={onClose}>
    <form className="space-y-4" onSubmit={save}>
      <Field label="Producto del menú"><select className={inputClass} value={menuKey} onChange={(event)=>setMenuKey(event.target.value)}>{data.menu_items.map((row)=><option key={row.source_key} value={row.source_key}>{row.name}</option>)}</select></Field>
      <div className="space-y-3">
        {components.map((component,index)=>{
          const selectedItem=recipeItems.find((item)=>item.id===component.item_id);
          return <div key={index} className={`rounded-[1rem] border p-3.5 ${component.controls_inventory?'border-cyanGlow/25 bg-cyanGlow/[0.06]':'border-amberGlow/25 bg-amberGlow/[0.06]'}`}>
            <div className="mb-3 flex items-center justify-between gap-3">
              <p className="text-[0.68rem] font-semibold uppercase tracking-[0.18em] text-mist">Componente {index+1}</p>
              <button type="button" className={`${dangerButton} px-3 py-2`} onClick={()=>setComponents((current)=>current.filter((_,i)=>i!==index))}>Quitar</button>
            </div>
            <div>
              <Field label="Artículo"><SearchableInventoryItemSelect items={recipeItems} value={component.item_id} ariaLabel={`Buscar componente ${index+1}`} onChange={(itemId)=>setComponents((current)=>current.map((row,i)=>i===index?{...row,item_id:itemId}:row))}/></Field>
              <div className="mt-3 grid gap-3 md:grid-cols-[minmax(0,1fr)_17rem] md:items-end">
                <Field label={`Cantidad por producto${component.controls_inventory?'':' (opcional)'}`}><div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-2"><input aria-label={`Cantidad del componente ${index+1}`} className={inputClass} type="number" min="0.001" step="0.001" required={component.controls_inventory} value={component.quantity_base} placeholder={component.controls_inventory?'Obligatoria':'Sin definir'} onChange={(event)=>setComponents((current)=>current.map((row,i)=>i===index?{...row,quantity_base:event.target.value}:row))}/><span className="whitespace-nowrap text-xs text-mist">{selectedItem?inventoryUnitLabels[selectedItem.base_unit]:'Unidad base'}</span></div></Field>
                <div className="flex min-h-[3rem] items-center justify-between gap-3 rounded-[0.85rem] border border-white/10 bg-black/15 px-3">
                  <span className="text-[0.68rem] font-semibold uppercase leading-4 tracking-[0.12em] text-mist">Descontar del inventario automáticamente</span>
                  <button type="button" role="switch" aria-label={`Descontar automáticamente el componente ${index+1}`} aria-checked={component.controls_inventory} className={`relative h-7 w-12 shrink-0 rounded-full border transition ${component.controls_inventory?'border-cyanGlow/55 bg-cyanGlow/30':'border-white/15 bg-white/[0.06]'}`} onClick={()=>setComponents((current)=>current.map((row,i)=>i===index?{...row,controls_inventory:!row.controls_inventory}:row))}><span className={`absolute top-1 h-[1.15rem] w-[1.15rem] rounded-full transition ${component.controls_inventory?'left-[1.55rem] bg-cyanGlow':'left-1 bg-mist'}`}/></button>
                </div>
              </div>
              {!component.controls_inventory?<p className="mt-3 rounded-[0.8rem] border border-amberGlow/15 bg-black/15 px-3 py-2 text-xs leading-5 text-amber-100">{component.quantity_base===''?'Componente descriptivo sin cantidad definida. No se descontará ni podrá costearse automáticamente.':'Se usará para calcular el costo, pero no generará movimientos automáticos de inventario.'}</p>:null}
            </div>
          </div>;
        })}
      </div>
      <button type="button" className={ghostButton} onClick={()=>setComponents((current)=>[...current,{item_id:recipeItems[0]?.id??'',controls_inventory:true,quantity_base:''}])}>Añadir componente</button>
      <div className="rounded-[0.9rem] border border-white/10 bg-black/15 p-4 text-sm text-mist">
        <p>{costSummary.isPartial?'Costo calculado parcial':'Costo calculado'}: <strong className="text-ivory">{costSummary.cost==null?'Sin costo conocido':money(costSummary.cost)}</strong>.</p>
        <p className="mt-2 text-xs">Todo componente con cantidad definida participa en el costo según la última compra real. Solo los marcados para descuento automático generan movimientos de inventario. El cambio afecta entregas futuras; cada consumo anterior conserva su receta y costo.</p>
      </div>
      <DialogButtons busy={busy} onClose={onClose} label="Guardar receta" disabled={invalid}/>
    </form>
  </Dialog>;
}

function InventoryImportDialog({ onClose, onImported }: { onClose: () => void; onImported: (message: string) => Promise<void> }) {
  const [parsed,setParsed]=useState<ParsedInventoryImport|null>(null); const [preview,setPreview]=useState<InventoryImportServerPreview|null>(null);
  const [fingerprint,setFingerprint]=useState(''); const [requestId,setRequestId]=useState(''); const [fileName,setFileName]=useState('');
  const [busy,setBusy]=useState(false); const [loadError,setLoadError]=useState<string|null>(null);
  useEffect(()=>{if(!loadError)return undefined;const timer=window.setTimeout(()=>setLoadError(null),getInventoryMessageDuration(true));return()=>window.clearTimeout(timer);},[loadError]);
  const inspect=async(file:File|undefined)=>{ if(!file)return; setBusy(true);setLoadError(null);setPreview(null);setParsed(null);setFileName(file.name);setRequestId(crypto.randomUUID()); try{ const buffer=await file.arrayBuffer(); const nextParsed=parseInventoryWorkbook(buffer); setParsed(nextParsed);setFingerprint(await inventoryImportFingerprint(buffer)); if(!nextParsed.errors.length)setPreview(await previewInventoryImport(nextParsed.payload)); }catch(reason){setLoadError(reason instanceof Error?reason.message:'No se pudo leer el archivo XLSX.');}finally{setBusy(false);} };
  const errors=[...(parsed?.errors??[]),...(preview?.errors??[])]; const warnings=[...(parsed?.warnings??[]),...(preview?.warnings??[])];
  const confirm=async()=>{ if(!parsed||!preview||errors.length||!fingerprint||!requestId)return; setBusy(true);setLoadError(null); try{ const result=await commitInventoryImport(requestId,fingerprint,parsed.payload); await onImported(`Importación completada: ${result.created_articles} artículos, ${result.created_presentations} presentaciones, ${result.created_menu_associations} asociaciones y ${result.created_initial_counts} conteos iniciales.`); }catch(reason){setLoadError(reason instanceof Error?reason.message:'No se pudo importar el archivo.');}finally{setBusy(false);} };
  return <Dialog title="Importar inventario" onClose={onClose}><div className="space-y-5"><p className="text-sm leading-6 text-mist">Selecciona un XLSX con las hojas Articulos, Presentaciones y ConsumoMenu. Primero se valida todo; no se guarda nada hasta confirmar. Las claves de producto deben ser las claves estables reales del menú.</p><Field label="Archivo XLSX"><input className={inputClass} type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange={(event)=>void inspect(event.target.files?.[0])}/></Field>{busy&&!parsed?<p className="text-sm text-cyanGlow">Analizando {fileName}…</p>:null}{loadError?<div role="alert" className="rounded-[0.9rem] border border-rose-300/30 bg-rose-300/10 p-3 text-sm text-rose-100">{loadError}</div>:null}
    {parsed?<div className="grid gap-3 sm:grid-cols-2"><Metric label="Artículos válidos" value={String(parsed.payload.articles.length)}/><Metric label="Presentaciones" value={String(parsed.payload.presentations.length)}/><Metric label="Asociaciones de menú" value={String(parsed.payload.menu_consumption.length)}/><Metric label="Conteos iniciales" value={String(parsed.payload.articles.filter((row)=>row.initial_quantity!=null).length)} tone={parsed.payload.articles.some((row)=>row.initial_quantity!=null)?'warn':undefined}/></div>:null}
    {preview?<div className="rounded-[1rem] border border-white/10 bg-black/20 p-4 text-sm text-mist"><p className="font-semibold text-ivory">Vista previa del servidor</p><p className="mt-2">Artículos: {preview.new_articles.length} nuevos · {preview.existing_articles.length} existentes</p><p>Presentaciones: {preview.new_presentations.length} nuevas · {preview.existing_presentations.length} existentes</p><p>Productos de menú: {preview.new_menu_products.length} nuevos · {preview.existing_menu_products.length} existentes</p><p>Asociaciones válidas: {preview.menu_association_count} · Conteos que se generarían: {preview.initial_count_count}</p></div>:null}
    {warnings.length?<div className="rounded-[0.9rem] border border-amberGlow/30 bg-amberGlow/[0.08] p-3 text-sm text-amber-100"><strong>Advertencias</strong><ul className="mt-2 list-disc space-y-1 pl-5">{[...new Set(warnings)].map((message)=><li key={message}>{message}</li>)}</ul></div>:null}{errors.length?<div role="alert" className="rounded-[0.9rem] border border-rose-300/30 bg-rose-300/10 p-3 text-sm text-rose-100"><strong>Errores y conflictos</strong><ul className="mt-2 list-disc space-y-1 pl-5">{[...new Set(errors)].map((message)=><li key={message}>{message}</li>)}</ul></div>:null}
    <p className="text-xs leading-5 text-mist">Una existencia vacía permanece desconocida y deja el artículo “Sin conteo inicial”. Un costo inicial sin existencia no crea saldo, recepción, compra ni gasto.</p><div className="flex flex-wrap justify-end gap-2"><button type="button" className={ghostButton} onClick={onClose}>Cancelar</button><button type="button" className={primaryButton} disabled={busy||!preview||errors.length>0} onClick={()=>void confirm()}>{busy?'Procesando…':'Confirmar importación'}</button></div></div></Dialog>;
}

function AdjustmentDialog({ data,itemId,busy,onClose,onSave }: DialogProps & {data:InventoryData;itemId:string}) { const item=data.items.find((row)=>row.id===itemId); const initial=item?.tracking_started_at==null; const [quantity,setQuantity]=useState(''); const [reason,setReason]=useState(''); const [costDisplay,setCostDisplay]=useState(''); const [costValue,setCostValue]=useState<number|null>(null); return <Dialog title={initial?'Registrar conteo inicial':'Registrar corrección compensatoria'} onClose={onClose}><form className="space-y-4" onSubmit={(e)=>{e.preventDefault();void onSave(initial?{action:'initial_count',item_id:itemId,quantity:Number(quantity),initial_unit_cost:costValue,reason}:{action:'correction',item_id:itemId,quantity_delta:Number(quantity),reason},initial?'Conteo inicial registrado.':'Corrección registrada sin alterar el historial.');}}><Field label="Artículo"><div className={lockedValueClass}>{item?.name ?? 'Artículo no disponible'} · {item?formatInventoryQuantity(item.balance,item.base_unit):''}</div></Field><Field label={initial?'Cantidad física inicial':'Cantidad a sumar o restar (usa signo negativo)'}><input className={inputClass} type="number" min={initial?'0':undefined} step="0.001" required value={quantity} onChange={(e)=>setQuantity(e.target.value)}/></Field>{initial?<Field label="Costo unitario inicial estimado o conocido (COP, opcional)"><input className={inputClass} inputMode="decimal" value={costDisplay} onChange={(e)=>{const formatted=inventoryMoneyInput(e.target.value);setCostDisplay(formatted.display);setCostValue(formatted.value);}}/><span className="mt-2 block text-xs text-mist">Si no lo conoces, deja el campo vacío: la cantidad se guardará con valoración explícitamente desconocida.</span></Field>:null}<Field label="Motivo"><textarea className={inputClass} required rows={3} value={reason} onChange={(e)=>setReason(e.target.value)}/></Field><DialogButtons busy={busy} onClose={onClose} label={initial?'Activar seguimiento':'Registrar corrección'} disabled={!item||quantity===''||!reason.trim()}/></form></Dialog>; }

interface DialogProps { busy:boolean; onClose:()=>void; onSave:(payload:Record<string,unknown>,message:string)=>Promise<void>; }
function Dialog({ title,onClose,children }:{title:string;onClose:()=>void;children:ReactNode}) { return <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/75 p-3 sm:items-center" role="dialog" aria-modal="true"><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-[1.4rem] border border-white/12 bg-[#0d0d13] p-5 shadow-2xl sm:p-7"><div className="mb-5 flex items-center justify-between gap-3"><h2 className="font-display text-3xl text-ivory">{title}</h2><button className={ghostButton} onClick={onClose} type="button">Cerrar</button></div>{children}</div></div>; }
function DialogButtons({busy,onClose,label,disabled}:{busy:boolean;onClose:()=>void;label:string;disabled?:boolean}) { return <div className="flex flex-wrap justify-end gap-2 pt-2"><button type="button" className={ghostButton} onClick={onClose}>Cancelar</button><button type="submit" className={primaryButton} disabled={busy||disabled}>{busy?'Guardando…':label}</button></div>; }
function Field({label,children}:{label:string;children:ReactNode}) { return <label className="block"><span className="mb-2 block text-xs font-semibold uppercase tracking-[0.16em] text-mist">{label}</span>{children}</label>; }
function SearchableInventoryItemSelect({items,value,onChange,ariaLabel}:{items:InventoryItem[];value:string;onChange:(itemId:string)=>void;ariaLabel:string}) { const [search,setSearch]=useState(''); const selection=getInventoryItemSearchSelection(items,value,search); const changeSearch=(nextSearch:string)=>{const next=getInventoryItemSearchSelection(items,value,nextSearch);setSearch(nextSearch);onChange(next.selectedItemId);}; return <div className="space-y-2"><input aria-label={ariaLabel} className={inputClass} value={search} onChange={(event)=>changeSearch(event.target.value)} placeholder="Buscar por nombre o código"/><select aria-label={`${ariaLabel}: resultado`} className={inputClass} value={value} disabled={!selection.options.length} onChange={(event)=>onChange(event.target.value)}>{selection.options.length?selection.options.map((item)=><option key={item.id} value={item.id}>{item.name} ({inventoryUnitLabels[item.base_unit]})</option>):<option value="">Sin artículos coincidentes</option>}</select></div>; }

function PageNavigation({page,hasMore,loading,onPrevious,onNext}:{page:number;hasMore:boolean;loading:boolean;onPrevious:()=>void;onNext:()=>void}) { return <nav className="mt-5 flex items-center justify-between gap-3" aria-label="Navegación de resultados"><button type="button" className={ghostButton} disabled={loading||page===0} onClick={onPrevious}>Anterior</button><span className="text-center text-xs text-mist">Página {page+1}{!loading&&!hasMore?' · Última página':''}</span><button type="button" className={ghostButton} disabled={loading||!hasMore} onClick={onNext}>Siguiente</button></nav>; }
function PageError({message}:{message:string}) { return <div role="alert" className="mt-5 rounded-[0.9rem] border border-rose-300/30 bg-rose-300/10 p-3 text-sm text-rose-100">{message}</div>; }
function Metric({label,value,tone}:{label:string;value:string;tone?:'warn'}) { return <article className={`rounded-[1.1rem] border p-4 ${tone==='warn'?'border-amberGlow/22 bg-amberGlow/[0.06]':'border-white/10 bg-white/[0.035]'}`}><p className="text-xs uppercase tracking-[0.16em] text-mist">{label}</p><p className="mt-2 font-display text-3xl text-ivory">{value}</p></article>; }
function StateCard({title,children}:{title:string;children:ReactNode}) { return <div className="mt-6 rounded-[1.1rem] border border-white/10 bg-white/[0.035] p-6"><h2 className="font-display text-2xl text-ivory">{title}</h2><p className="mt-2 text-sm text-mist">{children}</p></div>; }
function ActionCard({title,copy,action,onClick}:{title:string;copy:string;action:string;onClick:()=>void}) { return <article className={card}><h3 className="font-display text-2xl text-ivory">{title}</h3><p className="mt-2 text-sm leading-6 text-mist">{copy}</p><button className={`${primaryButton} mt-5`} onClick={onClick}>{action}</button></article>; }

const inputClass='w-full rounded-[0.9rem] border border-white/10 bg-obsidian/60 px-4 py-3 text-base text-ivory outline-none transition focus:border-cyanGlow/40';
const lockedValueClass='w-full rounded-[0.9rem] border border-white/10 bg-white/[0.04] px-4 py-3 text-base text-ivory';
const primaryButton='rounded-full border border-cyanGlow/30 bg-cyanGlow/12 px-4 py-2.5 text-xs font-semibold uppercase tracking-[0.18em] text-cyanGlow transition hover:bg-cyanGlow/18 disabled:cursor-not-allowed disabled:opacity-50';
const ghostButton='rounded-full border border-white/12 bg-white/[0.05] px-4 py-2.5 text-xs font-semibold uppercase tracking-[0.18em] text-ivory transition hover:border-cyanGlow/25 hover:bg-white/[0.09] disabled:cursor-not-allowed disabled:border-white/5 disabled:bg-white/[0.02] disabled:text-mist/40 disabled:opacity-50';
const dangerButton='rounded-full border border-rose-300/25 bg-rose-300/10 px-4 py-2.5 text-xs font-semibold uppercase tracking-[0.16em] text-rose-100 disabled:opacity-50';
const tabButton='shrink-0 rounded-full border px-4 py-2.5 text-xs font-semibold uppercase tracking-[0.16em] transition';
const card='rounded-[1.1rem] border border-white/10 bg-white/[0.035] p-5';
const sectionTitle='font-display text-3xl text-ivory';
const sectionCopy='mt-2 max-w-3xl text-sm leading-6 text-mist';
